toolUseResult.content:
import { createContext, useCallback, useContext, useEffect, useState } from "react";

import * as authApi from "../api/auth";
import { setUnauthorizedHandler, tokenStore } from "../api/client";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  // Only show the "checking" screen when there is a saved token to verify.
  const [checking, setChecking] = useState(() => Boolean(tokenStore.get()));
  const [notice, setNotice] = useState("");

  const logout = useCallback((message = "") => {
    tokenStore.clear();
    setUser(null);
    setNotice(message);
  }, []);

  useEffect(() => {
    setUnauthorizedHandler(() => logout("Your session has expired. Please log in again."));
  }, [logout]);

  // On page load, turn a saved token back into a user (or drop it if it expired).
  useEffect(() => {
    if (!tokenStore.get()) return;
    authApi
      .getMe()
      .then(setUser)
      .catch(() => {})
      .finally(() => setChecking(false));
  }, []);

  async function login(email, password) {
    const { access_token } = await authApi.login(email, password);
    tokenStore.set(access_token);
    const me = await authApi.getMe();
    setNotice("");
    setUser(me);
  }

  async function register(email, password) {
    await authApi.register(email, password);
    await login(email, password);
  }

  return (
    <AuthContext.Provider value={{ user, checking, notice, login, register, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}

// Small building blocks shared by every screen. The look lives in index.css.

export function Button({ variant = "chrome", busy = false, children, className = "", ...props }) {
  return (
    <button
      className={`btn btn-${variant} ${className}`}
      disabled={busy || props.disabled}
      {...props}
    >
      {busy ? "Working…" : children}
    </button>
  );
}

export function Panel({ title, children, className = "" }) {
  return (
    <section className={`panel ${className}`}>
      {title && <h2 className="panel-title">{title}</h2>}
      {children}
    </section>
  );
}

export function Field({ label, error, className = "", ...inputProps }) {
  return (
    <label className={`flex flex-col gap-1 ${className}`}>
      <span className="field-label">{label}</span>
      <input className={`field ${error ? "field-invalid" : ""}`} {...inputProps} />
      {error && <span className="text-xs font-semibold text-cherry-dark">{error}</span>}
    </label>
  );
}

export function Alert({ kind = "error", children }) {
  if (!children) return null;
  return (
    <p role={kind === "error" ? "alert" : "status"} className={`alert alert-${kind}`}>
      {children}
    </p>
  );
}

export function Spinner({ label = "Loading…" }) {
  return (
    <div className="flex items-center justify-center gap-3 py-10 text-cream" role="status">
      <span className="hubcap" aria-hidden="true" />
      <span className="font-display tracking-wider">{label}</span>
    </div>
  );
}

const priceFormat = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
export const formatPrice = (price) => priceFormat.format(price);

