@import "tailwindcss";

/*
  Retro chrome look, built from three ingredients only:
  a base colour, a light highlight on the top edge and a darker shadow below.
  Pressed buttons swap the outer shadow for an inner one so they sink in.
*/

@theme {
  --font-display: "Righteous", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Share Tech Mono", ui-monospace, monospace;

  --color-ink: #1f1b18;
  --color-cream: #f6efdf;
  --color-paper: #fbf6ea;
  --color-cherry: #cf2734;
  --color-cherry-dark: #8c1521;
  --color-teal: #2e8a91;
  --color-teal-dark: #1b5a5f;
  --color-steel: #7c838a;
  --color-amber: #f4cf62;
}

@layer base {
  body {
    @apply min-h-screen font-sans text-ink;
    background:
      radial-gradient(ellipse at top, #3a7d82 0%, transparent 60%),
      linear-gradient(180deg, #24575b 0%, #163a3d 100%);
    background-attachment: fixed;
  }
}

@layer components {
  /* Polished chrome strip: bright top, dark band in the middle, bright again below. */
  .chrome {
    background: linear-gradient(180deg, #ffffff 0%, #dfe3e7 40%, #a9b0b7 52%, #e4e7ea 100%);
    border: 1px solid var(--color-steel);
    box-shadow:
      inset 0 1px 0 #fff,
      inset 0 -1px 0 rgb(0 0 0 / 0.25),
      0 4px 10px rgb(0 0 0 / 0.35);
  }

  /* Car grille: thin vertical bars. */
  .grille {
    height: 10px;
    border-radius: 999px;
    background: repeating-linear-gradient(90deg, #2b2f33 0 6px, #c9ced3 6px 8px);
    box-shadow: inset 0 2px 3px rgb(0 0 0 / 0.6);
  }

  /* Hood emblem logo. */
  .emblem {
    @apply font-display text-2xl tracking-wide text-cherry sm:text-3xl;
    padding: 0.2rem 1.1rem;
    border-radius: 999px;
    text-shadow: 0 1px 0 #fff, 0 -1px 0 rgb(0 0 0 / 0.25);
  }

  /* Cream dashboard panel with a chrome rim and a thick bottom edge. */
  .panel {
    @apply rounded-2xl p-5;
    background: var(--color-cream);
    border: 4px solid #cfd4d8;
    box-shadow:
      0 0 0 1px var(--color-steel),
      inset 0 1px 0 rgb(255 255 255 / 0.9),
      inset 0 -3px 0 rgb(0 0 0 / 0.08),
      0 6px 0 #a59a80,
      0 12px 20px rgb(0 0 0 / 0.35);
  }
  .panel-title {
    @apply mb-4 font-display text-xl tracking-wide text-teal-dark;
    text-shadow: 0 1px 0 #fff;
  }

  /* Embossed pill buttons. */
  .btn {
    @apply inline-flex items-center justify-center rounded-full px-4 py-2 font-display text-sm tracking-wider uppercase select-none;
    transition:
      transform 80ms ease,
      box-shadow 80ms ease,
      filter 120ms ease;
    box-shadow:
      inset 0 1px 0 rgb(255 255 255 / 0.85),
      inset 0 -2px 0 rgb(0 0 0 / 0.2),
      0 3px 0 var(--btn-edge),
      0 5px 8px rgb(0 0 0 / 0.3);
  }
  .btn:hover:not(:disabled) {
    filter: brightness(1.06);
  }
  .btn:active:not(:disabled) {
    transform: translateY(3px);
