  .btn-teal {
    --btn-edge: #123f43;
    color: #fff;
    text-shadow: 0 -1px 0 rgb(0 0 0 / 0.35);
    background: linear-gradient(180deg, #5bb8bf 0%, #2e8a91 50%, #24747a 100%);
  }

  /* Recessed input fields. */
  .field-label {
    @apply text-xs font-bold tracking-widest text-teal-dark uppercase;
  }
  .field {
    @apply w-full rounded-lg px-3 py-2 text-ink;
    background: var(--color-paper);
    border: 1px solid #b3a88e;
    box-shadow:
      inset 0 2px 4px rgb(0 0 0 / 0.18),
      0 1px 0 rgb(255 255 255 / 0.9);
  }
  .field:focus {
    outline: 2px solid var(--color-teal);
    outline-offset: 1px;
  }
  .field-invalid {
    border-color: var(--color-cherry);
  }

  /* Odometer-style stock counter. */
  .gauge {
    @apply rounded-md px-2 py-1 font-mono text-lg tracking-[0.2em];
