    background: linear-gradient(180deg, #111 0%, #2a2a2a 100%);
    box-shadow:
      inset 0 2px 4px rgb(0 0 0 / 0.8),
      0 1px 0 rgb(255 255 255 / 0.7);
  }
  .gauge-empty {
    color: #ff6b6b;
  }

  /* Price shown on a little licence plate. */
  .plate {
    @apply rounded-md px-3 py-1 font-mono text-lg font-bold;
    background: #fffdf6;
    border: 2px solid var(--color-ink);
    box-shadow:
      inset 0 0 0 2px #fffdf6,
      inset 0 0 0 3px var(--color-ink),
      0 2px 0 rgb(0 0 0 / 0.25);
  }

  .chip {
    @apply rounded-full px-3 py-0.5 text-xs font-bold tracking-widest text-white uppercase;
    background: linear-gradient(180deg, #5bb8bf, #24747a);
    box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.5);
  }

  .stamp {
