  .hubcap {
    @apply inline-block size-7 rounded-full;
    background:
      radial-gradient(circle, #e9ecef 0 22%, transparent 23%),
      repeating-conic-gradient(#aab1b8 0 15deg, #f4f6f7 15deg 30deg);
    border: 3px solid #5e656c;
    animation: spin 0.9s linear infinite;
  }
