    setBusy(name);
    setMessage({ kind: "error", text: "" });
    try {
      await action();
      if (successText) setMessage({ kind: "success", text: successText });
    } catch (error) {
      setMessage({ kind: "error", text: error.message });
    } finally {
      setBusy("");
    }
  }

